--- a/src/main/java/com/pantryshare/reservation/ReservationService.java
+++ b/src/main/java/com/pantryshare/reservation/ReservationService.java
@@ -1,6 +1,16 @@
 package com.pantryshare.reservation;

 @Service
 @RequiredArgsConstructor
 public class ReservationService {
+    private final OfferRepository offers;
+    private final ReservationRepository reservations;
+
+    @Transactional
+    public Reservation reserve(Long offerId, Long memberId, int quantity) {
+        Offer offer = offers.findById(offerId).orElseThrow();
+        if (offer.getRemainingQuantity() < quantity) throw new SoldOutException();
+        offer.decrease(quantity);
+        return reservations.save(new Reservation(offerId, memberId, quantity));
+    }
 }
